INSERT INTO `grab_params_plotting` VALUES (1,1,'Water physicochemistry','Dissolved Oxygen - Field [mg/L]','WTW_DO','mg/L','WTW_DO_mgL_1',NULL,NULL,'basicPlot','A measure of how much oxygen is dissolved in the water and available to living aquatic organisms. Measured in the field with a handheld sensor.',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(2,2,'Water physicochemistry','Dissolved Oxygen - Field [%]','WTW_DO_sat','%','WTW_DO_sat_1',NULL,NULL,'basicPlot','A measure of the saturation of oxygen dissolved in the water. Measured in the field with a handheld sensor.',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(3,3,'Water physicochemistry','Temperature - Field [°C]','Temp','°C','WTW_Temp_degC_1',NULL,NULL,'basicPlot','Water temperature affected by air temperature stormwater runoff groundwater inflows turbidity and exposure to sunlight. Measured in the field with a handheld sensor.',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(4,4,'Water physicochemistry','pH - Field []','pH','-','WTW_pH_1',NULL,NULL,'basicPlot','Water pH measured in the field with a handheld sensor.',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(5,5,'Water physicochemistry','Conductivity - Field [µS/cm]','WTW_Spec_Cond','µS/cm','WTW_Spec_Cond_uScm_1',NULL,NULL,'basicPlot','A measure of the ability of an aqueous solution to carry an electrical current. It indicates the ionic effect in a water source (mineralization) and informs on the variation or changes in natural water. Measured in the field with a handheld sensor.',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(6,7,'Water physicochemistry','Alkalinity - Lab [meq/L]','Alk','meq/L','Alk_meqL',NULL,NULL,'basicPlot','Alkalinity is the water\'s capacity to resist changes in pH that would make the water more acidic. Measured in the laboratory from a sample.',0,'2020-10-26 12:05:25','2024-06-20 12:24:34'),(7,6,'Water physicochemistry','Turbidity - Field [NTU]','TURB','NTU','WTW_TURB_NTU',NULL,NULL,'basicPlot','Turbidity is the measure of relative clarity of the water measured in the field with a handheld sensor.',1,'2020-10-26 12:05:25','2024-06-20 12:24:34'),(8,8,'Stream morphometry','Reach depth - Field [cm]','Depth','cm','Reach_depth_avg_cm,Gage_obl_cm,Gage_vert_cm','Reach_depth_sd_cm',NULL,'multiPlot','Refers to the stream water depth calculated as the average depth of ten random measurements in the neighborhoods of the METALP station. Manually measured at each station maintenance. Vertical and oblique sections of the bazooka that are submersed. Used to intercalibrate the DEPTH sensor. Manually measured at each station maintenance.',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(9,9,'Dissolved organic carbon','Dissolved organic carbon - Lab [ppb]','DOC','ppb','DOC_avg_ppb','DOC_sd_ppb',NULL,'sdPlot','It informs on the potential source of carbon and energy for heterotrophic organisms and it contributes significantly to stream ecosystem metabolism. Measured in the laboratory from water samples (triplicates).',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(10,10,'Nutrients','Ammonium - Lab [µg/L]','NH4_nutrients','µg/L','NH4_avg_ugL',NULL,NULL,'basicPlot','Compounds resulting from the decomposition of organic matter if nitrogenous brought to the stream by surface run-off water. Measured in the laboratory from water samples (triplicates).',1,'2020-10-26 12:05:25','2021-01-21 10:21:29'),(11,11,'Nutrients','Soluble reactive phosphorus [µg/L] (old method)','SRP','µg/L','SRP_avg_ugL',NULL,NULL,'basicPlot','The labile form of phosphorus (P) used by plants and algae. Measured in the laboratory from water samples (triplicates).',1,'2020-10-26 12:05:25','2021-11-17 13:12:22'),(12,13,'Ions','Fluoride - Lab [mg/L]','Fl','mg/L','Fl_mgL',NULL,NULL,'basicPlot','Fluoride ionic content. Measured in the laboratory from water sample by Ion Chromatography (IC).',1,'2020-10-26 12:05:25','2021-11-17 13:19:13'),(13,14,'Ions','Chloride - Lab [mg/L]','Cl','mg/L','Cl_mgL',NULL,NULL,'basicPlot','Chloride ionic content. Measu